<script setup>
import { ref } from 'vue'
import { money, dateLabel, statuses } from '../lib/catalog.js'
import { api, notify } from '../lib/store.js'
import OrderDetails from './OrderDetails.vue'
const props = defineProps({ orders: Array, admin: Boolean }), emit = defineEmits(['update'])
const opened = ref(''), busy = ref(false), error = ref('')
async function cancel(order) { if (!window.confirm(`Bestellung ${order.id} stornieren? Der Gesamtbetrag von ${money(order.total)} einschließlich Versandkosten wird zurückerstattet.`)) return; busy.value = true; error.value = ''; try { const updated = await api(`/orders/${order.id}/cancel`, { method: 'PUT' }); emit('update', updated); notify('Die Bestellung wurde storniert.') } catch (e) { error.value = e.message } finally { busy.value = false } }
async function status(order, value) { busy.value = true; error.value = ''; try { const updated = await api(`/orders/${order.id}/status`, { method: 'PUT', body: { status: value } }); emit('update', updated); notify('Der Bestellstatus wurde gespeichert.') } catch (e) { error.value = e.message } finally { busy.value = false } }
</script>
<template><div class="orders-list"><p v-if="error" class="form-error" role="alert">{{ error }}</p><article v-for="order in orders" :key="order.id" class="order-card"><div class="order-row"><div><strong>{{ order.id }}</strong><small>{{ dateLabel(order.createdAt) }}</small><small v-if="admin">{{ order.customer.firstName }} {{ order.customer.lastName }}</small></div><span class="status-badge" :class="'status-' + order.status">{{ statuses[order.status] }}</span><strong>{{ money(order.total) }}</strong><button class="text-button" :aria-expanded="opened === order.id" @click="opened = opened === order.id ? '' : order.id">{{ opened === order.id ? 'Details schließen' : 'Details ansehen' }}</button></div><div v-if="opened === order.id" class="expanded-order"><OrderDetails :order="order" :admin="admin"><div v-if="admin && order.status !== 'cancelled'" class="status-edit"><label :for="'status-' + order.id">Bestellstatus ändern</label><select :id="'status-' + order.id" :value="order.status" :disabled="busy" @change="status(order, $event.target.value)"><option v-for="(label, value) in { new: statuses.new, processing: statuses.processing, shipped: statuses.shipped, delivered: statuses.delivered }" :key="value" :value="value">{{ label }}</option></select></div><button v-else-if="!admin && ['new', 'processing'].includes(order.status)" class="button button-outline danger" :disabled="busy" @click="cancel(order)">Bestellung stornieren</button></OrderDetails></div></article></div></template>
